mapper.select:
SELECT 
FROM TBL_REGULATORY_REPORT
WHERE DELETE_FLAG = 0

    AND REPORT_NO LIKE CONCAT('%', #{reportNo}, '%')


    AND REPORT_NAME LIKE CONCAT('%', #{reportName}, '%')


    AND TEMPLATE_ID = #{templateId}


    AND AUTHORITY_ID = #{authorityId}


    AND REPORT_STATUS = #{reportStatus}


    AND REPORT_PERIOD = #{reportPeriod}


    AND COMPANY_ID = #{companyId}

ORDER BY CREATED_TIME DESC

mapper.update:
UPDATE TBL_REGULATORY_REPORT
SET REPORT_STATUS = #{status}, UPDATED_TIME = SYSDATE
WHERE REPORT_ID = #{reportId}
